input.newString:
window.addEventListener('keydown', e => {
  // Unlock audio context on first interaction
  if (audioCtx.state !== 'running') audioCtx.resume();
  if (e.key === 'ArrowLeft') {
    ship.dx = -ship.speed;
    playMove();
  }
  if (e.key === 'ArrowRight') {
    ship.dx = ship.speed;
    playMove();
  }
});

